import{_ as p,o as t,c as r,a8 as s}from"./chunks/framework.BWjTbCIc.js";const i=JSON.parse('{"title":"中华基金中学 · 2022–2023 汇编（考试年未逐条注明） · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"cfss","school_zh":"中华基金中学","school_en":"The Chinese Foundation Secondary School","grade":"s1","year":"2022-23-source","year_label":"2022–2023 汇编（考试年未逐条注明）","type":"interview","title":"中华基金中学 · 2022–2023 汇编（考试年未逐条注明） · 中一 · 面试","anonymous":true,"source_ids":["CF014"],"rounds":["r1","unknown","r2"]},"headers":[],"relativePath":"reports/cfss/s1/2022-23-source-interview.md","filePath":"reports/cfss/s1/2022-23-source-interview.md"}'),n={name:"reports/cfss/s1/2022-23-source-interview.md"};function e(g,o,a,c,l,u){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="中华基金中学-·-2022–2023-汇编-考试年未逐条注明-·-中一-·-面试" tabindex="-1">中华基金中学 · 2022–2023 汇编（考试年未逐条注明） · 中一 · 面试 <a class="header-anchor" href="#中华基金中学-·-2022–2023-汇编-考试年未逐条注明-·-中一-·-面试" aria-label="Permalink to &quot;中华基金中学 · 2022–2023 汇编（考试年未逐条注明） · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/cfss">← 返回中华基金中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-cf014" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-cf014" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-cf014}&quot;">​</a></h2><p><strong>资料类型：</strong> 历史面试反馈汇编</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文</p><p><strong>回忆一：朗读与语文题</strong></p><p>中文面试回忆一：朗读一篇中文文章；改正一处错别字，须写出正确写法；重组句子1题；成语2至3题。</p><p><strong>小组讨论</strong></p><p>另有中文小组讨论：“朗诵帮不到学习，你认同这个说法吗？”反馈者认为小组讨论是主要环节。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>回忆二：分组与讨论</strong></p><p>中文面试回忆二：4人一组，中英文各有一场小组讨论。中文讨论比较烹饪与戏剧，哪一项未来较有发展空间及帮助；</p><p><strong>个人环节</strong></p><p>个人环节包括读文、阅读理解及重组句子。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>回忆二：图片故事与重排</strong></p><p>英文面试回忆二：4人各获一幅图片，先分别讲述自己图片的内容，再合作把4幅图排序并串成故事。老师随后要求更改排序，再讲另一个版本的故事。</p><p><strong>个人追问</strong></p><p>个人环节在讨论后进行，老师就图片和故事追问。</p><p><strong>未出现的环节</strong></p><p>该反馈明确称没有自我介绍，也没有个人背景问题。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>回忆三：小组讨论</strong></p><p>中文面试回忆三：4人小组讨论：“有人提议在学校加建泳池，你是否同意？说明原因。”</p><p><strong>个人环节</strong></p><p>个人环节朗读文章并回答问题，另有四字成语（如“袖手____”）、找错字及重组句子。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>回忆三：故事与问答</strong></p><p>英文面试回忆三：4人各讲述一幅相关图片，组成一个故事，再轮流回答故事相关问题。</p><p><strong>首轮总时长</strong></p><p>该份反馈称首轮整体约1.5小时，并未给出每项净作答时长。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>回忆四：阅读准备</strong></p><p>中文面试回忆四：先用5分钟阅读文章。</p><p><strong>文章情节</strong></p><p>内容为一老一少两位失明者相依为命；老者临终前留下一把琵琶，称弹断琴弦后打开盒子、读懂纸条便能重见光明。年轻人四处游历、不断弹琴，琴弦终于断了，却从路人口中得知纸条是空白，继而有所领悟。</p><p><strong>个人题目</strong></p><p>个人问题包括文章主旨、老者为什么这样做；另有2道成语填充、1道重组句子。</p><p><strong>小组讨论</strong></p><p>4人小组讨论若能选择一种超能力，会选隐形还是读心术。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>回忆四：图片故事</strong></p><p>英文面试回忆四：4人各看一幅图并讲故事，把4人的图片拼起来后再讲一次。</p><p><strong>个人追问</strong></p><p>个人追问：是否享受小组讨论？讨论中遇到哪些困难？最难忘的地方是什么？</p><p><strong>资料收取与发还</strong></p><p>该条同时记录：中文部分开始前收取小四至小六的学校手册及家课册，英文部分结束后发还。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>回忆五：候场与阅读</strong></p><p>中文面试回忆五：在操场等约10分钟后，到礼堂限时5分钟阅读中文文章，再到另一课室答题。</p><p><strong>个人题目</strong></p><p>个人题包括“____请命”成语填充、另一道未能记起的成语题、文章中心主旨及重组句子。</p><p><strong>小组讨论</strong></p><p>中文小组讨论电子游戏是否弊多于利，并讨论好处与坏处。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>回忆五：故事讨论</strong></p><p>英文面试回忆五：围绕一篇英文故事进行小组活动：最喜欢哪个角色？最想得到故事中的什么？最想问主角什么问题？另有故事重组。</p><p><strong>分组与评分观察</strong></p><p>该考生观察到从操场开始，每4名学生为一组，有老师跟随并评分；这属于个人观察，未据此确认评分细则。</p></blockquote><blockquote><p><strong>考核安排：</strong> 中文</p><p><strong>回忆六：报到与分组</strong></p><p>候考与中文面试回忆六：学校分时段放行，报到前5分钟才可入校；凭准考通知及身份证登记，获发注明时段、分组号码的贴纸贴于胸前。</p><p><strong>候场及准备材料</strong></p><p>先在楼下大堂等候人员到齐，再上二楼大堂，每人一张桌，提供笔、橡皮及A4笔记纸，派发小组讨论题及中文阅读文章，准备5分钟；这段时间会收取学生手册及家课册，查看后发还。</p><p><strong>个人答题</strong></p><p>随后每组3至4人进入课室，先单对单看iPad回答4题：文章题1道、错别字1道、成语2道（给出两个字，补全另两个字）。</p><p><strong>小组讨论</strong></p><p>再进行小组讨论：“如果你是运动推广大使，会怎样推动学生多做运动？”4人讨论4分钟。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>回忆六：英文图片故事</strong></p><p>英文面试回忆六：转至第二间课室进行英文小组讨论；每人先讲自己的一张图，再讨论如何连接4幅图组成故事。</p><p><strong>故事情节</strong></p><p>该组情节是一名学生因身高不足未能加入篮球队，要想办法解决。</p></blockquote><blockquote><p><strong>家长交流：</strong> 语言未注明</p><p><strong>回忆六：家长候场交流</strong></p><p>家长候场交流回忆六：家长在地下等候时，校长与家长交流并回答问题。</p><p><strong>校长讲话的家长转述</strong></p><p>家长转述，当时校长称约九成老师参与面试，约一半考生会获邀第二轮；届时由主任级或以上老师单对单面试，并与家长交谈，家长部分不影响学生分数。</p><p><strong>其他观察与适用范围</strong></p><p>反馈者没有见到学生协助。此为历史场次中的家长转述，不代表现行比例、人员安排或评分规则。</p></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文及英语</p><p><strong>补充回忆：中文环节</strong></p><p>综合面试补充回忆：另一段没有独立日期及轮次标题的反馈记录：中文个人环节先阅读5分钟再答题；中文小组讨论“电子游戏坏处比好处多？”</p><p><strong>英文合作故事</strong></p><p>英文小组看图说故事，先各自按图回答老师问题，最后4人合作排列图片顺序。</p><p><strong>另一道超能力题</strong></p><p>另有一条未注明轮次的问题：“如果有一种特异功能，你希望是读心术还是分身术？为什么？”其中“分身术”与其他记录的“隐形术”不同，分别保留。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>次轮回忆一：人数与时长</strong></p><p>综合面试回忆一：同一时段约十余名考生，入场后分组，该考生所在组有4人；全程约15分钟。</p><p><strong>学生面试</strong></p><p>学生逐一面试，先问为什么选择本校，再阅读英文文章并回答问题，另问地球自转加快会带来什么影响。</p><p><strong>家长面谈与不同感受</strong></p><p>家长每两人一组，主要被问有什么问题想问学校。该家长因认识同组家长而觉得气氛轻松；另一组有家长未到，留下的一位变成单独与老师面谈，该家长因此感到紧张。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>次轮回忆二：盆栽情境</strong></p><p>综合面试回忆二：看图提问盆栽种植装置的主题，以及露天盆栽种植的优点和缺点。</p><p><strong>水珠与病毒传播</strong></p><p>另问马桶有水珠溅出，与COVID-19及另一种反馈者忘记名称的病毒传播有何关系，怎样减少水珠溅出，病毒影响哪个器官；</p><p><strong>选校与职业问题</strong></p><p>还问申请了哪些学校、为什么报读中华基金，以及为何现在的园丁越来越少。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>次轮回忆二：朗读与词汇</strong></p><p>英语朗读回忆二：反馈者认为朗读难度较高；老师抽问生词意思，并问可用什么词替换“Mitigate”。</p></blockquote><blockquote><p><strong>综合面试：</strong> 中文及英语</p><p><strong>次轮回忆三：副校长面试</strong></p><p>综合面试回忆三：一对一见副校长。中文问为什么选择本校；英文看一幅有关欧洲滑雪场关闭的图片，再回答相关问题。</p></blockquote>',27)])])}const k=p(n,[["render",e]]);export{i as __pageData,k as default};
